INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("アヤネ", 2, 102301, 24, 2, "2030/12/17 14:59:59", "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 0.0, 10046, 0.0, 0.0, "2020/07/31 12:00:00", 24001, 401);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("アヤネ", 2, 102301, 24, 1, "2030/12/17 14:59:59", "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 0.0, 10046, 0.0, 2.21, "2020/07/31 12:00:00", 24002, 402);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("アヤネ", 2, 102301, 24, 2, "2030/12/17 14:59:59", "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 0.0, 10046, 0.0, 0.0, "2020/07/31 12:00:00", 24003, 403);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("アサヒ", 1, 192201, 24, 2, "2030/12/17 14:59:59", "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 0.0, 10046, 0.0, 1.99, "2020/07/31 12:00:00", 24004, 701);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("アサヒ", 2, 192201, 24, 1, "2030/12/17 14:59:59", "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 0.0, 10046, 0.0, 2.21, "2020/07/31 12:00:00", 24005, 702);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("アサヒ", 1, 192201, 24, 2, "2030/12/17 14:59:59", "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 0.0, 10046, 0.0, 3.33, "2020/07/31 12:00:00", 24006, 703);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("部員３", 2, 192301, 24, 2, "2030/12/17 14:59:59", "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 0.0, 10046, 0.0, 0.0, "2020/07/31 12:00:00", 24007, 801);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("部員３", 2, 192301, 24, 1, "2030/12/17 14:59:59", "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 0.0, 10046, 0.0, 2.68, "2020/07/31 12:00:00", 24008, 802);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("部員３", 2, 192301, 24, 2, "2030/12/17 14:59:59", "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 0.0, 10046, 0.0, 0.0, "2020/07/31 12:00:00", 24009, 803);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("", 1, 192501, 24, 1, "2030/12/17 14:59:59", "やった！", 0.0, 10046, 0.0, 0.0, "2020/07/31 12:00:00", 24010, 501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("", 1, 192501, 24, 1, "2030/12/17 14:59:59", "勝ったよ！", 0.0, 10046, 0.0, 0.0, "2020/07/31 12:00:00", 24011, 502);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("", 1, 192501, 24, 1, "2030/12/17 14:59:59", "いい調子！", 0.0, 10046, 0.0, 0.0, "2020/07/31 12:00:00", 24012, 503);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ミサト", 2, 113501, 24, 6, "2030/12/17 14:59:59", "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 0.0, 10046, 0.0, 5.33, "2020/07/31 12:00:00", 24013, 111);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ミサト", 2, 113501, 24, 1, "2030/12/17 14:59:59", "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 0.0, 10046, 0.0, 6.85, "2020/07/31 12:00:00", 24014, 112);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ミサト", 2, 113501, 24, 1, "2030/12/17 14:59:59", "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 0.0, 10046, 0.0, 3.0, "2020/07/31 12:00:00", 24015, 113);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ダイチ", 2, 192401, 24, 1, "2030/12/17 14:59:59", "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 0.0, 10046, 0.0, 6.11, "2020/07/31 12:00:00", 24016, 611);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ダイチ", 2, 192401, 24, 1, "2030/12/17 14:59:59", "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 0.0, 10046, 0.0, 6.75, "2020/07/31 12:00:00", 24017, 612);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ダイチ", 2, 192401, 24, 2, "2030/12/17 14:59:59", "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 0.0, 10046, 0.0, 0.0, "2020/07/31 12:00:00", 24018, 613);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ハツネ", 1, 113401, 24, 2, "2030/12/17 14:59:59", "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 0.0, 10046, 0.0, 4.52, "2020/07/31 12:00:00", 24019, 211);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ハツネ", 1, 113401, 24, 2, "2030/12/17 14:59:59", "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 0.0, 10046, 0.0, 3.89, "2020/07/31 12:00:00", 24020, 212);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ハツネ", 2, 113401, 24, 1, "2030/12/17 14:59:59", "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 0.0, 10046, 0.0, 13.49, "2020/07/31 12:00:00", 24021, 213);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("カヤ", 2, 106501, 24, 1, "2030/12/17 14:59:59", "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 0.0, 10046, 0.0, 3.17, "2020/07/31 12:00:00", 24022, 311);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("カヤ", 2, 106501, 24, 1, "2030/12/17 14:59:59", "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 0.0, 10046, 0.0, 4.42, "2020/07/31 12:00:00", 24023, 312);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("カヤ", 1, 106501, 24, 6, "2030/12/17 14:59:59", "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 0.0, 10046, 0.0, 2.89, "2020/07/31 12:00:00", 24024, 313);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("アヤネ", 3, 102301, 24, 4, "2030/12/17 14:59:59", "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 0.0, 10046, 0.0, 3.71, "2020/07/31 12:00:00", 24025, 421);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("アサヒ", 1, 192201, 24, 2, "2030/12/17 14:59:59", "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 0.0, 10046, 0.0, 5.1, "2020/07/31 12:00:00", 24026, 721);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("部員３", 3, 192301, 24, 1, "2030/12/17 14:59:59", "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 0.0, 10046, 0.0, 4.34, "2020/07/31 12:00:00", 24027, 821);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("", 1, 192501, 24, 1, "2030/12/17 14:59:59", "いい勝負だったよ\nまたやろうね", 0.0, 10046, 0.0, 0.0, "2020/07/31 12:00:00", 24028, 521);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ミサト", 2, 113501, 24, 1, "2030/12/17 14:59:59", "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 0.0, 10046, -360.0, 5.62, "2020/07/31 12:00:00", 24029, 101);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ミサト", 2, 113501, 24, 1, "2030/12/17 14:59:59", "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 0.0, 10046, -360.0, 9.58, "2020/07/31 12:00:00", 24030, 102);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ミサト", 2, 113501, 24, 2, "2030/12/17 14:59:59", "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 0.0, 10046, -360.0, 0.0, "2020/07/31 12:00:00", 24031, 103);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ミサト", 1, 113501, 24, 2, "2030/12/17 14:59:59", "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 0.0, 10046, -360.0, 9.13, "2020/07/31 12:00:00", 24032, 104);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("ミサト", 2, 113501, 24, 1, "2030/12/17 14:59:59", "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 0.0, 10046, -360.0, 8.27, "2020/07/31 12:00:00", 24033, 105);
